import{_ as e,o as l,c as d,ah as a}from"./chunks/framework.Bv6G8Ib6.js";const i="/arch-guidelines/assets/case_genai_1.CotL_sXU.png",n="/arch-guidelines/assets/case_genai_2.D9WfgcgI.png",s="/arch-guidelines/assets/case_genai_3.BgTN-TDF.png",c=JSON.parse('{"title":"ケーススタディ3: 社内問い合わせへの生成AIの導入範囲","description":"","frontmatter":{"sidebarDepth":4,"title":"ケーススタディ3: 社内問い合わせへの生成AIの導入範囲","author":"フューチャー株式会社","search":false,"head":[["meta",{"name":"robots","content":"noindex, nofollow"}]]},"headers":[],"relativePath":"documents/forSoftSkill/consensus/case_genai.md","filePath":"documents/forSoftSkill/consensus/case_genai.md"}'),f={name:"documents/forSoftSkill/consensus/case_genai.md"};function g(x,t,r,y,o,h){return l(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="ケーススタディ3-社内問い合わせへの生成aiの導入範囲" tabindex="-1">ケーススタディ3: 社内問い合わせへの生成AIの導入範囲 <a class="header-anchor" href="#ケーススタディ3-社内問い合わせへの生成aiの導入範囲" aria-label="Permalink to &quot;ケーススタディ3: 社内問い合わせへの生成AIの導入範囲&quot;">​</a></h1><h2 id="題材の設定" tabindex="-1">題材の設定 <a class="header-anchor" href="#題材の設定" aria-label="Permalink to &quot;題材の設定&quot;">​</a></h2><ul><li>相手: 国内の中堅の設備工事会社（電気・空調の設備工事。従業員約3,500人）。全国の支店と約300の作業所に社員が分散している。合意する先は、情報システム部で社内問い合わせの改善を担当する課長</li><li>自分たち: 相手の情報システム部から、社内問い合わせへの生成AIの導入を受託する予定の開発会社。構築と稼働後の運用保守を担う</li><li>現行: 情報システム部のヘルプデスク（外部委託を含む）と、総務部・人事部の窓口が、メール・電話・Teams で社内の問い合わせを受けている。件数は月約4,000件で、受付は平日9時〜18時。社内ポータルに FAQ 約400問があるが、探しにくく利用が少ない</li><li>計画: DX戦略で、社内問い合わせを生成AIで効率化することが決まっている。稼働は2027年10月を目標とする</li><li>きっかけ: 来年度予算の申請が2027年1月中旬に締め切られる。範囲によって初期構築費が大きく変わるため、12月の定例で範囲を決めたい</li><li>決めたいこと: 生成AIで社内問い合わせのどこまでに対応するか</li><li>方針（同業で規模が近い2社の公開資料から借用）: 問い合わせ対応を生成AIで効率化し、窓口の工数と社員の待ち時間を減らす</li></ul><h2 id="社内問い合わせへの生成aiの導入範囲についてのご相談" tabindex="-1">社内問い合わせへの生成AIの導入範囲についてのご相談 <a class="header-anchor" href="#社内問い合わせへの生成aiの導入範囲についてのご相談" aria-label="Permalink to &quot;社内問い合わせへの生成AIの導入範囲についてのご相談&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>社内の問い合わせは、作業所の始業前や夜間に届くものが多く、受付時間外に届いた問い合わせの回答は翌営業日になっています。</p><h3 id="相談事項" tabindex="-1">相談事項 <a class="header-anchor" href="#相談事項" aria-label="Permalink to &quot;相談事項&quot;">​</a></h3><p>規程や手順書を読めば答えられる質問まで、社員が窓口を介さずに解決できるようにするか、広げる場合はどこまで広げるかを相談させてください。</p><p>対応する範囲によって初期構築費が大きく変わり、範囲を後から広げると稼働が1年遅れます。そのため、来年度予算の申請前の12月中に決まることが好ましいと考えています。</p><h3 id="要件" tabindex="-1">要件 <a class="header-anchor" href="#要件" aria-label="Permalink to &quot;要件&quot;">​</a></h3><ul><li>業務要件 <ul><li>社内問い合わせを生成AIで効率化する（DX戦略で決定済み）</li><li>受付時間外の問い合わせにも答える</li><li>作業所からもスマートフォンの Teams で問い合わせられる</li></ul></li><li>システム要件 <ul><li>生成AIは、全社で利用している Microsoft 365 と Azure の契約の中で国内で動くものを使い、入力した内容を学習に使わせない</li></ul></li><li>その他 <ul><li>来年度予算の申請は2027年1月中旬に締め切られ、年度の途中では予算を追加できない</li><li>2027年10月に稼働する</li><li>全社員への汎用の生成AIの展開は、全社の生成AI活用として別に検討しており、今回の範囲に含めない</li></ul></li></ul><h3 id="構成案と推奨" tabindex="-1">構成案と推奨 <a class="header-anchor" href="#構成案と推奨" aria-label="Permalink to &quot;構成案と推奨&quot;">​</a></h3><p>社内問い合わせに生成AIで対応する範囲を、広い順に松・竹・梅の3段階で比べ、竹をご提案します。竹は、FAQ に加えて社内規程と手順書を調べて答えます。理由は次の2つです。</p><ul><li>問い合わせの約4割に、受付時間外でもその場で答えられる。窓口の対応工数を月約500時間減らせる（梅は月約140時間）。差は、1件あたり約30分かかる規程の質問の分</li><li>申請の起票は後から追加でき、効果を稼働後の利用状況で確かめてから判断できる</li></ul><p>窓口の直近6か月の記録を当社が分類すると、問い合わせは、答えるのに何が要るかで次の4つに分かれます。</p><p><img src="'+i+'" alt="構成案と推奨" width="1999" height="885"></p><p>費用の比と工数は、現時点の仮試算です。</p><p>【凡例】</p><ul><li>✅ 問題がない、⚠️ 条件つきで対応できるか負担がある、❌ 事実上対応できない</li><li>グレーの行: 3つの範囲で差が出ない観点</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">大分類</th><th style="text-align:left;">小分類</th><th style="text-align:left;">観点</th><th style="text-align:left;">松 申請の起票まで自動化する</th><th style="text-align:left;">竹 規程と手順書も調べて答える</th><th style="text-align:left;">梅 FAQ に答える</th></tr></thead><tbody><tr><td style="text-align:left;"></td><td style="text-align:left;">仕組み</td><td style="text-align:left;">生成AIが対応する範囲</td><td style="text-align:left;">竹に加え、申請の下書きを作ってワークフローに起票する。パスワードの再設定とアカウントの発行は、本人を確かめたうえで自動で済ませる。その他の申請の処理は現行どおり窓口が担う</td><td style="text-align:left;">梅に加え、全社員に公開している規程と手順書 約2,200文書から関係する箇所を探し、出典を添えて答える</td><td style="text-align:left;">承認済みの FAQ 約400問から答えを探して答える。FAQ に無い質問は窓口へ取り次ぐ</td></tr><tr><td style="text-align:left;">品質</td><td style="text-align:left;">使いやすさ</td><td style="text-align:left;">自己解決できる問い合わせ</td><td style="text-align:left;">✅ 月約2,260件、約6割</td><td style="text-align:left;">✅ 月約1,560件、約4割</td><td style="text-align:left;">⚠️ 月約840件、全体の約2割</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">受付時間外の問い合わせ（全体の約3割）への対応</td><td style="text-align:left;">✅ 申請の起票まで即時</td><td style="text-align:left;">✅ 規程の質問まで即答</td><td style="text-align:left;">⚠️ FAQ の範囲だけ即答</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">使う場所</td><td style="text-align:left;">✅ Teams（パソコン、スマートフォン）</td><td style="text-align:left;">✅ 同左</td><td style="text-align:left;">✅ 同左</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">正確さ</td><td style="text-align:left;">回答の誤り</td><td style="text-align:left;">⚠️ 竹と同じ。申請の内容の誤りは、本人の確認と承認で止める</td><td style="text-align:left;">⚠️ 規程の質問への回答の1割強に誤りや不足が出るおそれがある。出典を添え、社員が確かめられるようにする</td><td style="text-align:left;">✅ 承認済みの FAQ の文言で答える</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">改定への追従</td><td style="text-align:left;">✅ 竹と同じ</td><td style="text-align:left;">✅ 規程を差し替えれば回答に反映される</td><td style="text-align:left;">⚠️ FAQ を人が直す</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">セキュリティ</td><td style="text-align:left;">見せてはいけない文書が回答に出るおそれ</td><td style="text-align:left;">⚠️ 竹と同じ。加えて、生成AIにアカウントを操作する権限を与える</td><td style="text-align:left;">⚠️ 全社員に公開している文書に限る。公開範囲の設定を誤った文書があれば、回答に出るおそれがある</td><td style="text-align:left;">✅ FAQ だけを使う</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">生成AIに与える権限</td><td style="text-align:left;">⚠️ アカウントの操作を含む</td><td style="text-align:left;">✅ 読み取りだけ</td><td style="text-align:left;">✅ 読み取りだけ</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">入力した内容の扱い</td><td style="text-align:left;">✅ 国内の基盤で処理し、学習に使われない</td><td style="text-align:left;">✅ 同左</td><td style="text-align:left;">✅ 同左</td></tr><tr><td style="text-align:left;">費用</td><td style="text-align:left;">初期費用</td><td style="text-align:left;">初期構築費</td><td style="text-align:left;">⚠️ 梅の約9倍（竹に加え、ワークフローとアカウント管理との連携）</td><td style="text-align:left;">⚠️ 梅の約3倍（文書の取り込み、関係する箇所を探して答える仕組み、回答の正しさの評価）</td><td style="text-align:left;">✅ 基準</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">運用費</td><td style="text-align:left;">運用費（基盤の利用料と運用保守）</td><td style="text-align:left;">⚠️ 梅の約6倍</td><td style="text-align:left;">⚠️ 梅の約3倍</td><td style="text-align:left;">✅ 基準</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">基盤の利用料</td><td style="text-align:left;">⚠️ 年約600万円</td><td style="text-align:left;">✅ 年約300万円</td><td style="text-align:left;">✅ 年約100万円</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">効果</td><td style="text-align:left;">減らせる窓口の対応工数</td><td style="text-align:left;">✅ 月約620時間（申請は案内と差し戻しの手間 1件約10分を減らす）</td><td style="text-align:left;">✅ 月約500時間</td><td style="text-align:left;">⚠️ 月約140時間</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">貴社の作業</td><td style="text-align:left;">稼働までに貴社が担う作業</td><td style="text-align:left;">⚠️ 竹に加えて、申請 約20種類の手順の整理と、ワークフローの改修の調整 約6か月</td><td style="text-align:left;">⚠️ 梅に加えて、総務部・人事部による文書の棚卸し 約3か月</td><td style="text-align:left;">✅ FAQ の見直し 約1か月</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;">稼働後の窓口の運用</td><td style="text-align:left;">⚠️ 取り次がれた問い合わせに対応</td><td style="text-align:left;">⚠️ 同左</td><td style="text-align:left;">⚠️ 同左</td></tr><tr><td style="text-align:left;">納期</td><td style="text-align:left;">稼働時期</td><td style="text-align:left;">稼働時期</td><td style="text-align:left;">⚠️ 2028年7月</td><td style="text-align:left;">⚠️ FAQ の部分は2027年7月、規程の部分は2027年10月</td><td style="text-align:left;">✅ 2027年7月</td></tr></tbody></table><p>竹の費用のうち、初期構築費と運用保守費は利用の多さによらずかかり、基盤の利用料 年約300万円は問い合わせの件数に比例します。減らせる工数は、FAQ で答えられる質問と規程の質問のそれぞれ約6割を、自己解決できる想定で算出しました（当社が他社で導入した同種の仕組みで、窓口への再度の問い合わせが無かった割合）。</p><p>範囲を広げるほど自己解決できる問い合わせが増え、費用と回答の誤りのおそれも増えます。規程の質問まで広げるかと、申請の起票の自動化まで今回の予算に含めるかで、選ぶ範囲が決まります。</p><p><img src="'+n+'" alt="構成案と推奨" width="1999" height="934" loading="lazy"></p><p>以上から竹をご提案します。初期構築費と運用費が梅の約3倍（現時点の試算）になり、文書の棚卸し 約3か月（現時点の試算）が加わります。これらと引き換えに規程の質問まで自己解決を広げる、という方向について、まずはご所感を伺えますか。竹のデメリットと緩和策は、Appendix にまとめました。</p><h3 id="appendix-竹のデメリットと緩和策" tabindex="-1">Appendix: 竹のデメリットと緩和策 <a class="header-anchor" href="#appendix-竹のデメリットと緩和策" aria-label="Permalink to &quot;Appendix: 竹のデメリットと緩和策&quot;">​</a></h3><p>竹には次の4つのデメリットがあり、それぞれに緩和策を講じます。</p><p><img src="'+s+'" alt="竹を選んだ場合" width="1999" height="1104" loading="lazy"></p><h3 id="appendix-竹で生成aiが答える質問と、窓口へ取り次ぐ質問" tabindex="-1">Appendix: 竹で生成AIが答える質問と、窓口へ取り次ぐ質問 <a class="header-anchor" href="#appendix-竹で生成aiが答える質問と、窓口へ取り次ぐ質問" aria-label="Permalink to &quot;Appendix: 竹で生成AIが答える質問と、窓口へ取り次ぐ質問&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">分類</th><th style="text-align:left;">区分</th><th style="text-align:left;">竹での扱い</th></tr></thead><tbody><tr><td style="text-align:left;">生成AIが答える</td><td style="text-align:left;">FAQ で答えられる質問</td><td style="text-align:left;">生成AIが FAQ の文言で答える</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">規程や手順書を読めば答えられる質問</td><td style="text-align:left;">生成AIが出典を添えて答える</td></tr><tr><td style="text-align:left;">生成AIが案内する</td><td style="text-align:left;">申請や作業の依頼</td><td style="text-align:left;">申請の手順と申請画面を案内する。手続きは現行どおり窓口が対応する</td></tr><tr><td style="text-align:left;">窓口へ取り次ぐ</td><td style="text-align:left;">個別の判断が要る相談</td><td style="text-align:left;">答えず、総務部・人事部の窓口へ取り次ぐ</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">障害</td><td style="text-align:left;">答えず、情報システム部のヘルプデスクへ取り次ぐ</td></tr></tbody></table>',29)])])}const u=e(f,[["render",g]]);export{c as __pageData,u as default};
